def _toggle_connection_button(connected_button_name, connected):
    btn = getattr(ui, connected_button_name, None)
    if btn is not None:
        btn.setText("取消连接" if connected else "连接设备")


def _save_device_status(device_name, connected, resource=""):
    """更新 status.json 中的设备连接状态，刷新首页显示。"""
    import json
    import os
    from datetime import datetime
    _status_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "status.json")
    try:
        with open(_status_file, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        data = {"devices": [], "project": {}}
    now_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    for dev in data.get("devices", []):
        if dev["name"] == device_name:
            dev["connected"] = connected
            if resource:
                dev["resource"] = resource
            if connected:
                dev["last_connected"] = now_str
            break
    with open(_status_file, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    # 刷新首页
    if hasattr(ui, '_home_dots') and hasattr(ui, 'stackedWidget'):
        ui.stackedWidget.widget(0).update() if hasattr(ui.stackedWidget.widget(0), 'update') else None
        _reload_home_status(data)


def _update_project_status(project_name, status):
    """更新 status.json 中的测试项目状态。"""
    import json
    import os
    from datetime import datetime
    _status_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), "status.json")
    try:
        with open(_status_file, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        data = {"devices": [], "project": {}}
    now_str = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    data.setdefault("project", {})
    data["project"]["name"] = project_name
    data["project"]["status"] = status
    if status == "进行中":
        data["project"]["start_time"] = now_str
        data["project"]["estimated_end_time"] = ""
    elif status == "已结束":
        data["project"]["end_time"] = now_str
    with open(_status_file, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    if hasattr(ui, '_home_dots') and hasattr(ui, 'stackedWidget'):
        _reload_home_status(data)


def _reload_home_status(data):
    """用已加载的 status 数据刷新首页卡片。"""
    for dev in data.get("devices", []):
        name = dev["name"]
        if name in getattr(ui, '_home_dots', {}):
            color = "#22c55e" if dev.get("connected") else "#ef4444"
            ui._home_dots[name].setStyleSheet(f"background-color: {color}; border-radius: 5px;")
        if name in getattr(ui, '_home_res_labels', {}):
            res = dev.get("resource", "") or "未配置"
            ui._home_res_labels[name].setText(res)
        if name in getattr(ui, '_home_time_labels', {}):
            last = dev.get("last_connected", "")
            ui._home_time_labels[name].setText(f"上次连接: {last}" if last else "")


def _safe_close_handle(handle):
    """关闭设备句柄：委托 ``devices.handle_release``，与 AC/DC 控制器内重连前释放逻辑一致。"""
    try:
        release_resource_handle(handle)
    except Exception as e:
        logger.info(f"关闭设备失败: {e}")
        print(f"关闭设备失败: {e}")


_STATUS_COLOR_CONNECTED = QtGui.QColor(34, 197, 94)
_STATUS_COLOR_DISCONNECTED = QtGui.QColor(156, 163, 175)
_STATUS_COLOR_TEXT = QtGui.QColor(17, 24, 39)
_STATUS_ICON_CACHE = {}


def _make_status_icon(color):
    """生成一个圆点状态图标。"""
    key = color.name()
    if key in _STATUS_ICON_CACHE:
        return _STATUS_ICON_CACHE[key]
    pixmap = QtGui.QPixmap(12, 12)
    pixmap.fill(QtCore.Qt.transparent)
    painter = QtGui.QPainter(pixmap)
    painter.setRenderHint(QtGui.QPainter.Antialiasing)
    painter.setBrush(QtGui.QBrush(color))
    painter.setPen(QtCore.Qt.NoPen)
    painter.drawEllipse(1, 1, 10, 10)
    painter.end()
    icon = QtGui.QIcon(pixmap)
    _STATUS_ICON_CACHE[key] = icon
    return icon

def _normalize_equ_resource_text(text):
    """提取下拉框中真正的设备地址文本。"""
    if not text:
        return ""
    cleaned = str(text).strip()
    cleaned = cleaned.replace('●', '').replace('○', '').strip()
    if ' [' in cleaned:
        cleaned = cleaned.split(' [', 1)[0].strip()
    return cleaned

def _connection_state_label(tcp_addr, connected=False):
    """返回下拉框中资源的显示文本。"""
    return f'{tcp_addr}'

def _default_equ_placeholder():
    """下拉框默认占位项。"""
    return '请选择设备'

def _split_ipv4_tcp_endpoint(addr):
    """
    解析 Modbus TCP 地址：纯 IPv4，或 IPv4:端口。
    返回 (host, port_str)；不是此类地址时返回 None。
    解决 is_ipv4_stdlib 无法识别 \"192.168.x.x:端口\" 导致误走 VISA/SCPI 的问题。
    """
    if not addr or not isinstance(addr, str):
        return None
    addr = addr.strip()
    if ':' in addr:
        host, port = addr.rsplit(':', 1)
        if is_ipv4_stdlib(host) and port.isdigit():
            p = int(port)
            if 1 <= p <= 65535:
                return host, port
        return None
    if is_ipv4_stdlib(addr):
        return addr, '502'
    return None

def _refresh_combo_box_with_states(combo, resources, connected_resources, current_value=None):
    """按连接状态刷新下拉框，已连接资源保持可见但不可选。"""
    if combo is None:
        return
    previous = _normalize_equ_resource_text(current_value or combo.currentText())
    ordered_resources = [tcp_addr for tcp_addr in resources if tcp_addr and tcp_addr != _default_equ_placeholder()]
    # 手工输入的 IP:端口 / VISA 字符串可能不在 EQUList 里；已连接地址仍须出现在下拉项里才能正确回显
    if connected_resources:
        for addr in connected_resources:
            if addr and addr not in ordered_resources:
                ordered_resources.append(addr)
    ordered_resources.sort(key=lambda addr: (addr in connected_resources, addr))
    combo.blockSignals(True)
    try:
        combo.clear()
        combo.addItem(f'-- {_default_equ_placeholder()} --', '')
        for tcp_addr in ordered_resources:
            connected = tcp_addr in connected_resources
            is_current_choice = previous == tcp_addr
            item_text = _connection_state_label(tcp_addr, connected)
            combo.addItem(item_text, tcp_addr)
            index = combo.findData(tcp_addr)
            if index >= 0:
                item = combo.model().item(index)
                if item is not None:
                    item.setEnabled((not connected) or is_current_choice)
                    item.setForeground(QtGui.QBrush(_STATUS_COLOR_CONNECTED if connected else _STATUS_COLOR_DISCONNECTED))
                    item.setIcon(_make_status_icon(_STATUS_COLOR_CONNECTED if connected else _STATUS_COLOR_DISCONNECTED))
                    item.setToolTip("已连接，禁止再次选择" if connected and not is_current_choice else "可连接设备")
        if previous and previous in ordered_resources:
            target_index = combo.findData(previous)
        else:
            target_index = 0
        if target_index >= 0:
            combo.setCurrentIndex(target_index)
    finally:
        combo.blockSignals(False)

def _refresh_all_equ_combo_boxes(resources, connected_resources):
    """统一刷新所有设备下拉框状态。"""
    combo_names = [
        "comboBox_AC",
        "comboBox_DC1",
        "comboBox_DC2",
        "comboBox_DC3",
        "comboBox_DC4",
        "comboBox_DL850",
        "comboBox_WT3000",
        "comboBox_DEWETRON",
    ]
    for name in combo_names:
        combo = getattr(ui, name, None)
        current = _normalize_equ_resource_text(combo.currentText()) if combo is not None else None
        _refresh_combo_box_with_states(combo, resources, connected_resources, current)

def _set_equ_combo_locked(combo_name, locked):
    """统一锁定或解锁设备下拉框。"""
    combo = getattr(ui, combo_name, None)
    if combo is not None:
        combo.setEnabled(not locked)
        combo.setProperty("locked", locked)
        if locked:
            combo.setStyleSheet(
                "QComboBox[locked=\"true\"] { color: #111827; background-color: #F9FAFB; }"
                "QComboBox[locked=\"true\"]::drop-down { border: none; }"
            )
        else:
            combo.setStyleSheet("")

def _remove_equ_from_combo_boxes(tcp_addr):
    """兼容旧调用，改为刷新所有下拉框状态。"""
    connected = set(globals().get('_connected_equ_resources', set()))
    connected.add(tcp_addr)
    globals()['_connected_equ_resources'] = connected
    _refresh_all_equ_combo_boxes(globals().get('EQUList', []), connected)

def _restore_equ_to_combo_boxes(tcp_addr):
    """兼容旧调用，断开后恢复设备可选状态。"""
    connected = set(globals().get('_connected_equ_resources', set()))
    connected.discard(tcp_addr)
    globals()['_connected_equ_resources'] = connected
    _refresh_all_equ_combo_boxes(globals().get('EQUList', []), connected)

