def is_ip_address_format(addr):
    """判断输入是否为IPv4地址，支持可选端口（如 192.168.40.1:5000）。"""
    if not addr:
        return False
    ip_port_pattern = re.compile(r"^\d{1,3}(?:\.\d{1,3}){3}(?::\d{1,5})?$")
    return bool(ip_port_pattern.match(addr.strip()))

