def reset_wt_automation_state():
    """提交设定后重置WT自动化状态，确保下次开始会重新走自动化配置。"""
    global first_test, setting_status, messure_status, messsure_deatil_cofig, messure_project_cofig, WT_auto_messure_status
    global strTestStatusFlag
    # 运行中不允许重置自动化状态，避免中途把门闩清空导致后续命令无法触发测量。
    if 'strTestStatusFlag' in globals() and strTestStatusFlag == "运行":
        _append_debug_log(
            "[state_guard][skip] reset_wt_automation_state ignored because test is running"
        )
        return
    first_test = ''
    setting_status = ''
    messure_status = ''
    messsure_deatil_cofig = ''
    messure_project_cofig = ''
    WT_auto_messure_status = ''

def _sync_start_end_buttons():
    """根据当前项目的计数器决定启用/禁用开始/结束按钮。计数>=1启用，=0禁用。"""
    global flicker_append_count, harmonic_append_count, overloads_append_count
    current = ui.comboBox_PS.currentText()
    count = 0
    if current == '电压闪变':
        if 'flicker_append_count' not in globals():
            flicker_append_count = 0
        count = flicker_append_count
    elif current == '谐波电流':
        if 'harmonic_append_count' not in globals():
            harmonic_append_count = 0
        count = harmonic_append_count
    elif current == '过载能力测试':
        if 'overloads_append_count' not in globals():
            overloads_append_count = 0
        count = overloads_append_count
    ui.pushButton_StartTest.setEnabled(count >= 1)
    ui.pushButton_EndTest.setEnabled(count >= 1)

def _reset_current_project_count():
    """试验完成后重置当前项目的计数器为0，并更新label显示。"""
    global flicker_append_count, harmonic_append_count, overloads_append_count
    current = ui.comboBox_PS.currentText()
    if current == '电压闪变':
        flicker_append_count = 0
        uiThaiDianYaShanBian.label_append_count.setText("0")
    elif current == '谐波电流':
        harmonic_append_count = 0
        uiThaiXieBoDianLiu.label_append_count.setText("0")
    elif current == '过载能力测试':
        overloads_append_count = 0
        uiThaiOverLoads.label_append_count.setText("0")

