def DC_IV_Commands_Set(strArrayTestStepSingle: list, a: list, DC: str):
    global DC_num, command_list_DC, per_dc_factor
    # I-V曲线命令（按厂家选择）；未配置时避免抛出 KeyError 导致流程中断
    if a is None:
        strtimenow = now_to_datenow()
        logger.error(f"{DC} IV command list is empty")
        print(f"{strtimenow} {DC} IV command list is empty")
        return strArrayTestStepSingle
    dc_index = DC_num.get(DC, "")
    dc_factor = per_dc_factor.get(dc_index, "")
    command_array = command_list_DC.get(dc_factor, [])
    if not command_array:
        # 仍然继续下发 IVC 曲线命令（a 内通常是 IVC:IT / IVC:VT），否则会表现为“功率变化命令没生成”
        strtimenow = now_to_datenow()
        logger.warning(f"{DC} factor is empty or unsupported: '{dc_factor}', will send IVC commands only")
        print(f"{strtimenow} {DC} factor is empty or unsupported: '{dc_factor}', will send IVC commands only")
    
    strArraySingle = ["" for _ in range(10)]
    S1Command = "*IDN?"
    strArraySingle[0] = "AC"
    strArraySingle[1] = "query"
    strArraySingle[2] = S1Command
    strArraySingle[8] = 2
    strArrayTest.append(strArraySingle)
    strArrayTestStepSingle.append(strArraySingle)

    if command_array:
        strArraySingle = ["" for _ in range(10)]
        S1Command = command_array[0]
        strArraySingle[0] = DC
        strArraySingle[1] = "write"
        strArraySingle[2] = S1Command
        strArrayTest.append(strArraySingle)
        strArrayTestStepSingle.append(strArraySingle)

    for i in range(len(a)):
        strArraySingle = ["" for _ in range(10)]
        S1Command = a[i]
        strArraySingle[0] = DC
        strArraySingle[1] = "write"
        strArraySingle[2] = S1Command
        strArrayTest.append(strArraySingle)
        strArrayTestStepSingle.append(strArraySingle)
    # strArraySingle = ["" for _ in range(10)]
    # S1Command = a[0]
    # strArraySingle[0] = DC
    # strArraySingle[1] = "write"
    # strArraySingle[2] = S1Command
    # strArrayTest.append(strArraySingle)
    # strArrayTestStepSingle.append(strArraySingle)

    # strArraySingle = ["" for _ in range(10)]
    # S1Command = a[1]
    # strArraySingle[0] = DC
    # strArraySingle[1] = "write"
    # strArraySingle[2] = S1Command
    # strArrayTest.append(strArraySingle)
    # strArrayTestStepSingle.append(strArraySingle)

    if command_array:
        strArraySingle = ["" for _ in range(10)]
        S1Command = command_array[1]
        strArraySingle[0] = DC
        strArraySingle[1] = "write"
        strArraySingle[2] = S1Command
        strArrayTest.append(strArraySingle)
        strArrayTestStepSingle.append(strArraySingle)

    strArraySingle = ["" for _ in range(10)]
    S1Command = "*IDN?"
    strArraySingle[0] = "AC"
    strArraySingle[1] = "query"
    strArraySingle[2] = S1Command
    strArraySingle[8] = 2
    strArrayTest.append(strArraySingle)
    strArrayTestStepSingle.append(strArraySingle)

    return strArrayTestStepSingle

# 谐波电流测试追加
def thaixiebodianliuAppend():
    global strAddTestFlag, harmonic_append_count
    if 'harmonic_append_count' not in globals():
        harmonic_append_count = 0
    strAddTestFlag = "0" if harmonic_append_count == 0 else "1"
    mode = "覆盖" if harmonic_append_count == 0 else "追加"
    ui.textEdit_ReturnMessage.append(f"[谐波电流] 第{harmonic_append_count + 1}次{mode}模式，开始生成命令...")
    thaixiebodianliuSend()

