    def get_time(time_edit_name, combo_box_name, ui=uiThaiFixedPF):
        """
        通过控件名获取转换后的时间值
        参数:
            time_edit_name: 时间输入框的控件名（字符串）
            combo_box_name: 单位下拉框的控件名（字符串）
            ui: ui对象，默认为uiThaiFixedPF
        返回:
            float: 转换后的时间值
        """
        time_edit = getattr(ui, time_edit_name)
        combo_box = getattr(ui, combo_box_name)
        
        time_value = time_edit.toPlainText() if hasattr(time_edit, 'toPlainText') else time_edit.text()
        time_unit = combo_box.currentText()
        f_set_time = float(time_value)
        return SetTimeFunction(f_set_time, time_unit)

