#日期转换函数
def now_to_datenow(format_string="%Y-%m-%d %H:%M:%S"):
    time_stamp = int(time.time())
    time_array = time.localtime(time_stamp)
    str_date = time.strftime(format_string, time_array)
    return str_date

#转换时间--转换到毫秒级
def now_to_datenowminseconde():
    time_stamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    return time_stamp

#转换时间--转换到毫秒级
def now_to_datenowdata():
    time_stamp = datetime.datetime.now().strftime('%Y/%m/%d')
    return time_stamp

#转换时间--转换到当前时间
def now_to_datenowlog(format_string="%Y%m%d%H%M%S"):
    time_stamp = int(time.time())
    time_array = time.localtime(time_stamp)
    str_date = time.strftime(format_string, time_array)
    return str_date

#转换数据格式
def ChangeDateFormat(strData):
    if strData != "":
        ilen = len(strData) - 3
        str222 = strData[ilen:ilen + 1]
        if str222 == "+":
            str333 = strData[ilen:]
            inumber = int(str333)
            inumber1 = pow(10, inumber)
            str444 = strData[0:ilen - 1]
            inumber2 = float(str444)
            inumber3 = inumber1 * inumber2
            inumber4 = round(inumber3, 2)
            strreturnvalue = str(inumber4)
            return strreturnvalue
        elif str222 == "-":
            str333 = strData[ilen:]
            inumber = int(str333)
            inumber1 = pow(10, inumber)
            str444 = strData[0:ilen - 1]
            inumber2 = float(str444)
            inumber3 = inumber1 * inumber2
            inumber4 = round(inumber3, 2)
            strreturnvalue = str(inumber4)
            return strreturnvalue
        else:
            return strData
    else:
        return strData

