def DCGetIVValueFunction(strVmp,strImp,strVoc,strIsc,strPF,DCNumber):
    global ArrayfDCCurrValue, per_dc_factor, command_list_DC
    # 兼容功率百分比输入格式：
    # - "80" / "80%" / "80 %"
    # - "0.8"（按 80% 处理）
    def _parse_percent(v):
        if v is None:
            raise ValueError("percent is None")
        vs = str(v).strip()
        if vs.endswith('%'):
            vs = vs[:-1].strip()
        p = float(vs)
        # 兼容 0~1 的小数写法（0.8 -> 80%）
        if 0 < p <= 1:
            p *= 100.0
        return p

    dc_type = ""
    dc_type = per_dc_factor.get(str(DCNumber))
    # 如果 DC 厂家类型未配置/未知，旧逻辑会直接走到函数末尾返回 None，
    # 进而导致命令文件里完全没有 I-V/功率变化命令。
    # 这里做一个保底：默认按 Chroma 的 IVC:IT / IVC:VT 方式生成曲线命令。
    if not dc_type or dc_type not in ("Chroma", "Keysight", "Itech"):
        try:
            _append_debug_log(f"[DCGetIVValueFunction][warn] unknown dc_type={dc_type!r} for DC{DCNumber}, fallback to 'Chroma'")
        except Exception:
            pass
        dc_type = "Chroma"
    if dc_type and dc_type == "Chroma":
        print(f"dc_type--{dc_type}")
        DCParArray = ["" for ii in range(128)]
        DCArray = [["" for ii in range(128)] for jj in range(2)]
        strDCArray = [["" for ii in range(128)] for jj in range(2)]
        strArrayIVValue = []
        try:
            fDCVmp = float(strVmp)
            fDCImp = float(strImp)
            fDCVoc = float(strVoc)
            fDCIsc = float(strIsc)
            fPf = _parse_percent(strPF)

        except Exception as e:
            return "1"
        else:
            fPf = 0.01 * fPf
            fDCIsc = fDCIsc * fPf
            fDCImp = fDCImp * fPf

            if ArrayfDCCurrValue[int(DCNumber)] <= fDCIsc:
                return "2"
            else:
                if fDCImp == fDCIsc or fDCVmp==fDCVoc:
                    return "1"
                else:
                    fParC2 = (fDCVmp / fDCVoc - 1) / math.log(1 - fDCImp / fDCIsc) #chroma公式

                    fParC1 = (1 - fDCImp / fDCIsc) * math.exp(-1 * fDCVmp / (fParC2 * fDCVoc))
                    print(1)
                    fFF = (fDCVmp * fDCImp) / (fDCVoc * fDCIsc)
                    for i in range(128):
                        DCParArray[i] = 0 + i * (1 / 127)

                    for j in range(128):
                        DCArray[0][j] = round((1 - DCParArray[j]) * fDCIsc, 3)
                        strDCArray[0][j] = '%.3f' % DCArray[0][j]

                    for k in range(128):
                        DCArray[1][k] = round(math.fabs(math.log(math.fabs((1 - DCArray[0][k] / fDCIsc) / fParC1 + 1)) * fParC2 * fDCVoc), 3)
                        strDCArray[1][k] = '%.3f' % DCArray[1][k]

                    str1 = "IVC:IT "
                    str2 = "IVC:VT "
                    for i in range(len(strDCArray[0])):
                        if i == 0:
                            str1 = str1 + strDCArray[0][i]
                        else:
                            str1 = str1 + "," + strDCArray[0][i]

                    for i in range(len(strDCArray[1])):
                        if i == 0:
                            str2 = str2 + strDCArray[1][i]
                        else:
                            str2 = str2 + "," + strDCArray[1][i]
                    print(str1)
                    strArrayIVValue.append(str1)
                    print(str2)
                    strArrayIVValue.append(str2)
                    return strArrayIVValue
    elif dc_type and dc_type == "Keysight":
        DCParArray = ["" for ii in range(1024)]
        DCArray = [["" for ii in range(1024)] for jj in range(2)]
        strDCArray = [["" for ii in range(1024)] for jj in range(2)]
        strArrayIVValue = []
        try:
            fDCVmp = float(strVmp)
            fDCImp = float(strImp)
            fDCVoc = float(strVoc)
            fDCIsc = float(strIsc)
            fPf = _parse_percent(strPF)

        except Exception as e:
            return "1"
        else:
            fPf = 0.01 * fPf
            fDCIsc = fDCIsc * fPf
            fDCImp = fDCImp * fPf

            if fDCImp == fDCIsc or fDCVmp==fDCVoc:
                return "1"
            else:
                fParC2 = (fDCVmp / fDCVoc - 1) / math.log(1 - fDCImp / fDCIsc)

                fParC1 = (1 - fDCImp / fDCIsc) * math.exp(-1 * fDCVmp / (fParC2 * fDCVoc))
                print(1)
                fFF = (fDCVmp * fDCImp) / (fDCVoc * fDCIsc)
                for i in range(1024):
                    DCParArray[i] = 0 + i * (1 / 1023)

                for j in range(1024):
                    DCArray[0][j] = round((1 - DCParArray[j]) * fDCIsc, 3)
                    strDCArray[0][j] = '%.3f' % DCArray[0][j]

                for k in range(1024):
                    DCArray[1][k] = round(math.fabs(math.log(math.fabs((1 - DCArray[0][k] / fDCIsc) / fParC1 + 1)) * fParC2 * fDCVoc), 3)
                    strDCArray[1][k] = '%.3f' % DCArray[1][k]

                str1 = "SAS:TABL1:CURR "
                str2 = "SAS:TABL1:VOLT "
                for i in range(len(strDCArray[0])):
                    if i == 0:
                        str1 = str1 + strDCArray[0][i]
                    else:
                        str1 = str1 + "," + strDCArray[0][i]

                for i in range(len(strDCArray[1])):
                    if i == 0:
                        str2 = str2 + strDCArray[1][i]
                    else:
                        str2 = str2 + "," + strDCArray[1][i]
                print(str2)
                strArrayIVValue.append(str2)
                print(str1)
                strArrayIVValue.append(str1)
                return strArrayIVValue
    elif dc_type and dc_type == "Itech":
        # Itech：使用 SOL:USER:* 方式写入四参数（同样按功率百分比缩放电流）
        strArrayIVValue = []
        try:
            fDCVmp = float(strVmp)
            fDCImp = float(strImp)
            fDCVoc = float(strVoc)
            fDCIsc = float(strIsc)
            fPf = _parse_percent(strPF)
        except Exception:
            return "1"
        else:
            fPf = 0.01 * fPf
            fDCIsc = fDCIsc * fPf
            fDCImp = fDCImp * fPf
            # 电流上限检查（若数组未初始化则跳过）
            try:
                if ArrayfDCCurrValue[int(DCNumber)] <= fDCIsc:
                    return "2"
            except Exception:
                pass
            strArrayIVValue.append(f"SOL:USER:VOC {fDCVoc}")
            strArrayIVValue.append(f"SOL:USER:IMP {fDCImp}")
            strArrayIVValue.append(f"SOL:USER:VMP {fDCVmp}")
            strArrayIVValue.append(f"SOL:USER:ISC {fDCIsc}")
            return strArrayIVValue

    # 兜底：理论上不会走到这里
    return "1"

def get_enumwindows():
    hwnd_list = {}
    def foo(hwnd, result):
        if win32gui.IsWindow(hwnd) and \
            win32gui.IsWindowEnabled(hwnd) and \
                win32gui.IsWindowVisible(hwnd):
                hwnd_list.update({hwnd: win32gui.GetWindowText(hwnd)})

    win32gui.EnumWindows(foo, 0)
    return hwnd_list

