def mppt_read_config_file(test_vdc_now, d_number, vdc_list):
    """
        选择直流源配置文件
    """
    test_tt = {}
    handle_upper_dict = get_enumwindows()
    dc_handle = list(handle_upper_dict.keys())[
            list(handle_upper_dict.values()).index('Choose file to read.')]
    
    win32gui.EnumChildWindows(
        dc_handle, lambda hwnd, parm: parm.update(
            {hwnd:win32gui.GetWindowText(hwnd)}), test_tt)
    
    win32gui.ShowWindow(dc_handle, win32con.SW_SHOWNORMAL)
    win32gui.SetForegroundWindow(dc_handle)

    # 选择当前测试直流源参数配置文档
    address_D_list = [key for key, value in test_tt.items() if '地址: ' in value]
    address_D = int(address_D_list[0])
    left_D, top_D, right_D, bottom_D = win32gui.GetWindowRect(address_D)
    pyautogui.moveTo(
            left_D + 5, 
            top_D + 10, 
            duration=0.5)
    pyautogui.click()
    pyautogui.hotkey('ctrl', 'a', interval=0.5)
    pyperclip.copy('D:\直流源设置保存')
    pyautogui.hotkey('ctrl', 'v', interval=0.5)
    time.sleep(1)
    # try:
    #     address_D1 = list(test_tt.keys())[
    #             list(test_tt.values()).index('地址区段')]
    # except:
    #     address_D1 = list(test_tt.keys())[
    #             list(test_tt.values()).index('地址区段工具栏')]
    
    # left_D1, top_D1, right_D1, bottom_D1 = win32gui.GetWindowRect(address_D1)
    # pyautogui.moveTo(
    #         left_D1 + 30, 
    #         top_D1 + 10,
    #         duration=0.5)
    # pyautogui.click()
    pyautogui.press('enter', interval=0.5)
    time.sleep(1)

    if '文件名(&N):' in test_tt.values():
        # file_path 是固定6槽位（Vmin/Vnom/Vmax/Vdc1/Vdc2/Vdc3），但未勾选的槽位是空字符串。
        # 为了让 test_vdc_now 与“实际被勾选的槽位”对齐，这里按非空槽位映射索引。
        file_path_list = Mppt_step2.get('file_path', []) if 'Mppt_step2' in globals() else []
        slot_indices = [i for i, p in enumerate(file_path_list) if str(p).strip() != '']
        if test_vdc_now >= len(slot_indices):
            return f"未找到对应Vdc配置槽位: test_vdc_now={test_vdc_now}, slot_indices={slot_indices}"
        file_slot = slot_indices[test_vdc_now]

        file_name_input_handle = list(test_tt.keys())[
            list(test_tt.values()).index('文件名(&N):')]

        left_ether, top_ether, right_ether, bottom_ether = win32gui.GetWindowRect(file_name_input_handle)
        print(left_ether, top_ether, right_ether, bottom_ether)
        pyautogui.moveTo(
            left_ether + DC_STATIC_MPPT_TEST['DC_IV_choose'][0], 
            top_ether + DC_STATIC_MPPT_TEST['DC_IV_choose'][1], 
            duration=0.5)

        pyautogui.doubleClick()
        pyautogui.hotkey('ctrl', 'a', interval=0.5)
        if d_number >= len(vdc_list) or file_slot >= len(vdc_list[d_number]):
            return f"vdc_list索引越界: d_number={d_number}, file_slot={file_slot}, vdc_list_len={len(vdc_list)}"
        vdc_value = vdc_list[d_number][file_slot]
        if str(vdc_value).strip() == '':
            return f"该槽位未配置Vdc文件: d_number={d_number}, file_slot={file_slot}"
        pyperclip.copy(vdc_value)
        pyautogui.hotkey('ctrl', 'v', interval=0.5)
        confirm_buttom_handle =  list(test_tt.keys())[
            list(test_tt.values()).index('确定')]
        left_ether, top_ether, right_ether, bottom_ether = win32gui.GetWindowRect(confirm_buttom_handle)
        pyautogui.moveTo(
            left_ether + DC_STATIC_MPPT_TEST['DC_IV_confirm'][0], 
            top_ether + DC_STATIC_MPPT_TEST['DC_IV_confirm'][1],
            duration=0.5)
        pyautogui.click()
        time.sleep(1)
        
        return 1

