def translate_to_bluesight(text, value=None):
    """
    SCPI转蓝点直流源
    value: 要设置的新值（可选），如果不传则使用默认值
    """
    command_map = {
        "OUTP ON":  (0x0BB8, 0x00AA),  
        "OUTP OFF": (0x0BB8, 0x0055),
        "Vmp":      (0x1B64, 0x0000),    # 默认值为0
        "Voc":      (0x1B6A, 0x0000),    # 默认值为0
        "Pmp":      (0x1B62, 0x0000),    # 默认值为0
        "Isc":      (0x1B6C, 0x0000),    # 默认值为0
        "Custom":   (0x1B61, 0x0002),   
        "FF" :      (0x1B69, 0x0320),  #默认0.8
    }
    
    if text not in command_map:
        raise ValueError(f"未知的SCPI命令: {text}")
    
    addr, default_val = command_map[text]
    
    # 如果传入了value，使用新值，否则使用默认值
    if value is not None:
        return (addr, value)
    else:
        return (addr, default_val)


