            def _safe_click(obj, attr, slot):
                """安全连接信号：如果 obj 有 attr 属性则连接，否则打印警告。"""
                if hasattr(obj, attr):
                    getattr(obj, attr).clicked.connect(slot)
                else:
                    print(f"[WARN] {type(obj).__name__} 缺少 {attr}，跳过信号连接", flush=True)

